import { useState, useEffect } from 'react';
import { GameEngine } from '../game/gameEngine';

interface MultiplayerLobbyProps {
  gameEngine: GameEngine;
  playerName: string;
  onGameJoined: (gameId: string) => void;
  onBack: () => void;
}

export const MultiplayerLobby = ({ gameEngine, playerName, onGameJoined, onBack }: MultiplayerLobbyProps) => {
  const [availableGames, setAvailableGames] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [creatingGame, setCreatingGame] = useState(false);
  const [joiningGame, setJoiningGame] = useState<string | null>(null);

  useEffect(() => {
    loadAvailableGames();
    const interval = setInterval(loadAvailableGames, 5000); // Refresh every 5 seconds
    return () => clearInterval(interval);
  }, []);

  const loadAvailableGames = async () => {
    try {
      const games = await gameEngine.getAvailableGames();
      setAvailableGames(games);
      setLoading(false);
    } catch (error) {
      console.error('Failed to load games:', error);
      setLoading(false);
    }
  };

  const handleCreateGame = async () => {
    setCreatingGame(true);
    try {
      const gameId = await gameEngine.createMultiplayerGame(4, 'competitive');
      onGameJoined(gameId);

      // Track analytics
      gameEngine.trackAnalyticsEvent('multiplayer_game_created', {
        gameMode: 'competitive',
        maxPlayers: 4
      });
    } catch (error) {
      console.error('Failed to create game:', error);
      setCreatingGame(false);
    }
  };

  const handleJoinGame = async (gameId: string) => {
    setJoiningGame(gameId);
    try {
      await gameEngine.joinMultiplayerGame(gameId);
      onGameJoined(gameId);

      // Track analytics
      gameEngine.trackAnalyticsEvent('multiplayer_game_joined', {
        gameId
      });
    } catch (error) {
      console.error('Failed to join game:', error);
      setJoiningGame(null);
    }
  };

  return (
    <div className="multiplayer-lobby">
      <div className="lobby-header">
        <button onClick={onBack} className="back-btn">← Back</button>
        <h2>Multiplayer Lobby</h2>
        <div className="player-info">Playing as: {playerName}</div>
      </div>

      <div className="lobby-actions">
        <button 
          onClick={handleCreateGame}
          disabled={creatingGame}
          className="create-game-btn primary"
        >
          {creatingGame ? 'Creating...' : '🎮 Create New Game'}
        </button>
      </div>

      <div className="available-games">
        <h3>Available Games</h3>
        {loading ? (
          <div className="loading">Loading games...</div>
        ) : availableGames.length === 0 ? (
          <div className="no-games">No games available. Create one!</div>
        ) : (
          <div className="games-list">
            {availableGames.map((game) => (
              <div key={game.id} className="game-card">
                <div className="game-info">
                  <span className="game-host">Host: {game.hostName}</span>
                  <span className="game-mode">{game.gameMode}</span>
                  <span className="player-count">
                    {game.players.length}/{game.maxPlayers} players
                  </span>
                </div>
                <button 
                  onClick={() => handleJoinGame(game.id)}
                  disabled={joiningGame === game.id || game.players.length >= game.maxPlayers}
                  className="join-btn"
                >
                  {joiningGame === game.id ? 'Joining...' : 
                   game.players.length >= game.maxPlayers ? 'Full' : 'Join Game'}
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="lobby-stats">
        <div className="stat">
          <span className="stat-label">Active Games:</span>
          <span className="stat-value">{availableGames.length}</span>
        </div>
      </div>
    </div>
  );
};
